<template>
  <v-app :theme="isDark ? 'dark' : 'light'">
    <v-app-bar
      v-if="!$route.meta.hideLayout"
      flat
      style="border-bottom: 1px solid #e5e7eb"
    >
      <v-btn
        v-if="!layoutSettings.isHorizontal || $vuetify.display.smAndDown"
        size="small"
        class="mx-3"
        color="primary"
        variant="tonal"
        @click="drawer = !drawer"
      >
        <v-icon size="22">mdi-menu</v-icon>
      </v-btn>

      <v-toolbar-title
        class="font-weight-bold mx-0 px-0 cursor-pointer"
        @click="$router.push('/')"
      >
        Vue<span class="text-grey">Dashboard</span>
      </v-toolbar-title>

      <v-spacer />

      <div v-if="layoutSettings.isHorizontal" class="hidden-sm-and-down">
        <v-btn variant="text" @click="$router.push({ name: 'UserS' })"
          >Users</v-btn
        >
        <v-btn variant="text" @click="$router.push({ name: 'AddUser' })"
          >Add User</v-btn
        >
        <v-btn variant="text" @click="$router.push({ name: 'SettingsPage' })"
          >Settings</v-btn
        >
      </div>

      <v-spacer v-if="layoutSettings.isHorizontal" class="hidden-sm-and-down" />

      <v-switch
        v-model="isDark"
        inset
        hide-details
        class="mx-2"
        @change="toggleTheme"
      ></v-switch>

      <v-menu v-if="isLoggedIn">
        <template v-slot:activator="{ props }">
          <v-btn icon v-bind="props" class="ml-2">
            <v-avatar color="primary" size="35">
              <span class="text-white">
                {{ currentUser?.name?.substring(0, 1).toUpperCase() || "U" }}
              </span>
            </v-avatar>
          </v-btn>
        </template>
        <v-list elevation="3" rounded="lg">
          <v-list-item
            title="My Profile"
            prepend-icon="mdi-account"
            @click="$router.push({ name: 'ProfilePage' })"
          ></v-list-item>
          <v-divider></v-divider>
          <v-list-item
            title="Logout"
            prepend-icon="mdi-logout"
            color="red"
            @click="logout"
          ></v-list-item>
        </v-list>
      </v-menu>
    </v-app-bar>

    <v-navigation-drawer
      v-if="!$route.meta.hideLayout"
      v-model="drawer"
      :location="layoutSettings.isRtl ? 'right' : 'left'"
      :temporary="layoutSettings.isHorizontal"
      width="260"
      class="custom-drawer"
    >
      <v-toolbar
        flat
        v-if="!layoutSettings.isHorizontal"
        style="background-color: transparent"
      >
        <v-toolbar-title class="font-weight-bold">
          Vue<span class="text-grey">Dashboard</span>
        </v-toolbar-title>
      </v-toolbar>

      <v-list nav>
        <v-list-item
          class="listItemHover"
          title="Users"
          prepend-icon="mdi-account-group"
          @click="$router.push({ name: 'UserS' })"
        />
        <v-list-item
          class="listItemHover"
          title="Add User"
          prepend-icon="mdi-account-plus"
          @click="$router.push({ name: 'AddUser' })"
        />
        <v-list-item
          class="listItemHover"
          title="Settings"
          prepend-icon="mdi-cog"
          @click="$router.push({ name: 'SettingsPage' })"
        />
      </v-list>
    </v-navigation-drawer>

    <v-main>
      <router-view />
    </v-main>
  </v-app>
</template>

<script setup>
import { ref, onMounted, watch } from "vue";
import { useTheme } from "vuetify";
import { useRouter, useRoute } from "vue-router";

const theme = useTheme();
const router = useRouter();
const route = useRoute();

const drawer = ref(true);
const isDark = ref(theme.global.current.value.dark);
const layoutSettings = ref({ isRtl: false, isHorizontal: false });

const isLoggedIn = ref(!!localStorage.getItem("token"));
const currentUser = ref(
  JSON.parse(localStorage.getItem("currentUser") || "{}")
);

// تحديث الحالة عند تغيير المسار
const updateAuthStatus = () => {
  isLoggedIn.value = !!localStorage.getItem("token");
  currentUser.value = JSON.parse(localStorage.getItem("currentUser") || "{}");
};

watch(
  () => route.path,
  () => {
    updateAuthStatus();
    // إغلاق الدرور تلقائياً في الموبايل عند الانتقال لصفحة جديدة
    if (window.innerWidth < 960 && layoutSettings.value.isHorizontal) {
      drawer.value = false;
    }
  }
);

const toggleTheme = () => {
  theme.global.name.value = isDark.value ? "dark" : "light";
};

const logout = () => {
  localStorage.removeItem("token");
  localStorage.removeItem("currentUser");
  updateAuthStatus();
  router.push({ name: "LoginPage" });
};

const loadSettings = () => {
  const savedSettings = localStorage.getItem("layoutSettings");
  if (savedSettings) {
    layoutSettings.value = JSON.parse(savedSettings);
    // لو الوضع Horizontal، نخلي الدرور مقفول ديفولت في الشاشات الكبيرة
    if (layoutSettings.value.isHorizontal && window.innerWidth > 960) {
      drawer.value = false;
    }
  }

  const savedColor = localStorage.getItem("primaryColor");
  if (savedColor) {
    theme.themes.value.light.colors.primary = savedColor;
    theme.themes.value.dark.colors.primary = savedColor;
  }
};

onMounted(() => {
  loadSettings();
  window.addEventListener("layout-changed", loadSettings);
});
</script>

<style scoped>
.listItemHover:hover {
  transition: 0.3s all ease-in-out;
  cursor: pointer;
  background-color: rgba(33, 150, 243, 0.1);
}
.custom-drawer {
  transition: 0.3s all ease-in-out !important;
}
/* لضبط شكل السويتش في الهيدر */
:deep(.v-selection-control) {
  min-height: auto !important;
}
</style>
