<template>
  <v-container class="fill-height d-flex align-center justify-center">
    <v-card width="500" class="pa-6" elevation="3" rounded="lg">
      <v-card-title class="text-center text-h5 font-weight-bold mb-4">
        Register Now
      </v-card-title>

      <v-form
        ref="formRef"
        v-model="isFormValid"
        @submit.prevent="handleRegister"
      >
        <v-text-field
          v-model="user.name"
          label="Full Name"
          :rules="[rules.required]"
          variant="outlined"
          prepend-inner-icon="mdi-account-outline"
        ></v-text-field>

        <v-text-field
          v-model="user.email"
          label="Email"
          type="email"
          :rules="[rules.required, rules.email]"
          variant="outlined"
          prepend-inner-icon="mdi-email-outline"
        ></v-text-field>

        <v-select
          v-model="user.role"
          :items="['admin', 'user']"
          label="Select Role"
          :rules="[rules.required]"
          variant="outlined"
          color="primary"
          prepend-inner-icon="mdi-shield-account-outline"
        ></v-select>

        <v-text-field
          v-model="user.password"
          label="Password"
          type="password"
          :rules="[rules.required, rules.min8]"
          variant="outlined"
          prepend-inner-icon="mdi-lock-outline"
        ></v-text-field>

        <v-btn
          type="submit"
          color="success"
          block
          size="large"
          class="mt-4"
          :disabled="!isFormValid"
        >
          Create Account
        </v-btn>
      </v-form>

      <div class="text-center mt-4">
        Already have an account?
        <a href="#" @click.prevent="$router.push({ name: 'LoginPage' })">
          Login here
        </a>
      </div>
    </v-card>
  </v-container>
</template>

<script setup>
import { ref } from "vue";
import { useRouter } from "vue-router";

const router = useRouter();
const formRef = ref(null);
const isFormValid = ref(false);

const user = ref({
  name: "",
  email: "",
  password: "",
  role: "user",
});

// رسائل الخطأ اللي هتظهر تحت كل حقل
const rules = {
  required: (v) => !!v || "This field is required",
  email: (v) => /.+@.+\..+/.test(v) || "E-mail must be valid",
  min8: (v) => (v && v.length >= 8) || "Must be at least 8 characters",
};

const handleRegister = async () => {
  // تفعيل الفليديشن يدوياً للتأكد قبل الحفظ
  const { valid } = await formRef.value.validate();

  if (valid) {
    let users = JSON.parse(localStorage.getItem("user")) || [];

    // التأكد إن الإيميل مش متسجل قبل كدا
    if (users.find((u) => u.email === user.value.email)) {
      alert("This email is already registered!");
      return;
    }

    const newUser = {
      id: Date.now().toString(),
      name: user.value.name,
      email: user.value.email,
      role: user.value.role,
      password: user.value.password,
      createdAt: new Date().toISOString().split("T")[0],
    };

    users.push(newUser);
    localStorage.setItem("user", JSON.stringify(users));

    alert("Account created successfully! Please login.");
    router.push({ name: "LoginPage" });
  }
};
</script>
<style scoped>
/* خلفية متناسقة مع صفحة اللوجن */
.register-bg {
  background: linear-gradient(135deg, #e0eafc 0%, #cfdef3 100%);
}

.auth-card {
  border: 1px solid rgba(255, 255, 255, 0.4);
  backdrop-filter: blur(10px);
  transition: all 0.3s ease-in-out;
}

.register-btn {
  text-transform: none;
  letter-spacing: 0.5px;
  transition: transform 0.2s ease;
}

.register-btn:hover:not(:disabled) {
  transform: translateY(-3px);
}

/* تحسين شكل الروابط */
a:hover {
  text-decoration: underline !important;
}

/* استايل الموبايل */
@media (max-width: 600px) {
  .v-card {
    padding: 24px !important;
  }
  .text-h4 {
    font-size: 1.5rem !important;
  }
}
</style>
