<template>
  <v-container class="fill-height d-flex align-center justify-center">
    <v-card width="400" class="pa-6" elevation="3" rounded="lg">
      <v-card-title class="text-center text-h5 font-weight-bold mb-4">
        Login
      </v-card-title>

      <v-alert
        v-if="errorMessage"
        type="error"
        variant="tonal"
        class="mb-4"
        closable
      >
        {{ errorMessage }}
      </v-alert>

      <v-form ref="formRef" v-model="isFormValid" @submit.prevent="handleLogin">
        <v-text-field
          v-model="email"
          label="Email"
          type="email"
          variant="outlined"
          :rules="[rules.required, rules.email]"
          placeholder="example@mail.com"
          prepend-inner-icon="mdi-email-outline"
        ></v-text-field>

        <v-text-field
          v-model="password"
          label="Password"
          type="password"
          variant="outlined"
          :rules="[rules.required, rules.min]"
          prepend-inner-icon="mdi-lock-outline"
        ></v-text-field>

        <v-btn
          type="submit"
          color="primary"
          block
          size="large"
          class="mt-4"
          :disabled="!isFormValid"
        >
          Login
        </v-btn>
      </v-form>

      <div class="text-center mt-4">
        Don't have an account?
        <a href="#" @click.prevent="$router.push({ name: 'RegisterPage' })">
          Register Now
        </a>
      </div>
    </v-card>
  </v-container>
</template>

<script setup>
import { ref } from "vue";
import { useRouter } from "vue-router";

const router = useRouter();
const formRef = ref(null);
const isFormValid = ref(false);
const email = ref("");
const password = ref("");
const errorMessage = ref("");

// قواعد التحقق (Validation Rules)
const rules = {
  required: (value) => !!value || "This field is required.",
  min: (v) => (v && v.length >= 6) || "Password must be at least 6 characters.",
  email: (value) => {
    const pattern =
      /^(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/;
    return pattern.test(value) || "Invalid e-mail format.";
  },
};

const handleLogin = async () => {
  // التحقق من الفورم برمجياً
  const { valid } = await formRef.value.validate();

  if (valid) {
    let users = JSON.parse(localStorage.getItem("user")) || [];
    let existingUser = users.find((u) => u.email === email.value);

    if (!existingUser) {
      errorMessage.value = "User not found. Please register.";
      return;
    }

    if (existingUser.password !== password.value) {
      errorMessage.value = "Incorrect password!";
      return;
    }

    // تسجيل الدخول
    localStorage.setItem("token", "fake-jwt-token");
    localStorage.setItem(
      "currentUser",
      JSON.stringify({
        id: existingUser.id,
        name: existingUser.name,
        email: existingUser.email,
      })
    );

    router.push({ name: "UserS" });
  }
};
</script>
